import { mkdirSync, writeFileSync } from 'node:fs';

const required = [
  'NG_APP_API_BASE_URL',
  'NG_APP_SUPABASE_URL',
  'NG_APP_SUPABASE_ANON_KEY',
];
const missing = required.filter((name) => !process.env[name]);

if (missing.length > 0) {
  console.error(`Missing env vars: ${missing.join(', ')}`);
  process.exit(1);
}

const output = [
  '// AUTO-GENERATED by scripts/set-env.mjs. Do not edit or commit.',
  'export const environmentGenerated = {',
  `  apiBaseUrl: ${JSON.stringify(process.env.NG_APP_API_BASE_URL.replace(/\/+$/, ''))},`,
  `  supabaseUrl: ${JSON.stringify(process.env.NG_APP_SUPABASE_URL)},`,
  `  supabaseAnonKey: ${JSON.stringify(process.env.NG_APP_SUPABASE_ANON_KEY)},`,
  '} as const;',
  '',
].join('\n');

mkdirSync('src/environments', { recursive: true });
writeFileSync('src/environments/environment.generated.ts', output);
